
import type { CheckoutSubscriptionRecurringShipping } from './CheckoutSubscriptionRecurringShipping.js';
import type { MoneyValue } from './MoneyValue.js';
import type { SubscriptionIntervalOption } from './SubscriptionIntervalOption.js';

/** Renewal terms a subscription checkout commits the buyer to. Frozen when the session's order was created, so later plan changes do not alter them. */ export type CheckoutSubscriptionTerms = { "billing_interval": "daily" | "weekly" | "monthly" | "yearly" | (string & {}); /** Number of billing intervals between recurring charges. Format: int32. */ "billing_interval_count": number; /** minItems: 1. */ "billing_interval_options": Array<SubscriptionIntervalOption>; /** Minimum commitment in months, when the plan has one. Format: int32. */ "contract_term_months"?: number; /** Fee charged when the buyer cancels before the contract term ends, when the plan has one. */ "early_termination_fee_money"?: MoneyValue; /** Plan name shown to the buyer. */ "plan_name": string; /** Whole-number quantity; fractional quantities are not supported. Format: int32. */ "quantity": number; /** minItems: 1. */ "quantity_options": Array<number>; "recurring_shipping"?: CheckoutSubscriptionRecurringShipping; /** Charge for one billing interval before tax: each line's unit price times its quantity, plus modifiers. */ "recurring_total_money": MoneyValue; /** One-time fee charged with the first payment, when the plan has one. */ "setup_fee_money"?: MoneyValue; /** Flint subscription plan ID the terms come from. */ "subscription_plan_id": string; /** Days before the first recurring charge, when the plan has a trial. Format: int32. */ "trial_period_days"?: number; };
